import{_ as i,a0 as o,w as r,s as d,I as s,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"在 Snap 中玩轉 OpenStack | LCTT x X-CMD","titleTemplate":false,"description":"在 Snap 中玩轉 OpenStack | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Snap 中玩轉 OpenStack | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Snap 中玩轉 OpenStack | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170706 OpenStack in a Snap","title":"在 Snap 中玩轉 OpenStack","tag":"201708","desc":""},"relativePath":"201708/20170706 OpenStack in a Snap.md","filePath":"[post].md"}'),c={name:"201708/20170706 OpenStack in a Snap.md"};function k(u,n,m,h,g,b){const p=o("Link");return r(),d("div",null,[n[29]||(n[29]=s("h1",{id:"在-snap-中玩轉-openstack",tabindex:"-1"},[a("在 Snap 中玩轉 OpenStack "),s("a",{class:"header-anchor",href:"#在-snap-中玩轉-openstack","aria-label":"Permalink to “在 Snap 中玩轉 OpenStack”"},"​")],-1)),n[30]||(n[30]=s("p",null,[s("img",{src:"https://insights.ubuntu.com/wp-content/uploads/646b/openstaack-in-a-snap.png",alt:""})],-1)),n[31]||(n[31]=s("p",null,"OpenStack 非常複雜，許多社區成員都在努力使 OpenStack 的部署和操作更加容易。其中大部分時間都用來改善相關工具，如：Ansible、Puppet、Kolla、Juju、Triple-O 和 Chef (僅舉幾例)。但是，如果我們降低一下標準，並且還能使包的體驗更加簡單，將會怎樣呢？",-1)),s("p",null,[n[1]||(n[1]=a("我們正在努力通過 snap 包來實現這一點。snap 包是一種新興的軟件分發方式，這段來自 ",-1)),e(p,{href:"http://snapcraft.io/"},{default:t(()=>[...n[0]||(n[0]=[a("snapcraft.io",-1)])]),_:1}),n[2]||(n[2]=a(" 的介紹很好的總結了它的主要優點：",-1)),n[3]||(n[3]=s("em",null,"snap 包可以快速安裝、易於創建、安全運行而且能自動地事務化更新，因此你的應用程序總是能保持最新的狀態並且永遠不會被破壞。",-1))]),n[32]||(n[32]=l('<h3 id="捆綁軟件" tabindex="-1">捆綁軟件 <a class="header-anchor" href="#捆綁軟件" aria-label="Permalink to “捆綁軟件”">​</a></h3><p>單個 snap 包可以內嵌多個不同來源的軟件，從而提供一個能夠快速啓動和運行的解決方案。當你安裝 snap 包時，你會發現安裝速度是很快的，這是因為單個 snap 包捆綁了所有它需要的依賴。這和安裝 deb 包有些不同，因為它需要下載所有的依賴然後分別進行安裝。</p><h3 id="snap-包製作簡單" tabindex="-1">Snap 包製作簡單 <a class="header-anchor" href="#snap-包製作簡單" aria-label="Permalink to “Snap 包製作簡單”">​</a></h3><p>在 Ubuntu 工作的時候，我花了很多時間為 Debian 製作 OpenStack 的安裝包。這是一種很特殊技能，需要花很長時間才能理解其中的細微差別。與 snap 包相比，deb 包和 snap 包在複雜性上的差異有天壤之別。snap 包簡單易行，並且相當有趣。</p><h3 id="snap-包的其它特性" tabindex="-1">Snap 包的其它特性 <a class="header-anchor" href="#snap-包的其它特性" aria-label="Permalink to “Snap 包的其它特性”">​</a></h3><ul><li>每個 snap 包都安裝在其獨有的只讀 squashfs 文件系統中。</li><li>每個 snap 包都運行在一個由 AppArmor 和 seccomp 策略構建的嚴格沙箱環境中。</li><li>snap 包能事務更新。新版本的 snap 包會安裝到一個新的只讀 squashfs 文件系統中。如果升級失敗，它將回滾到舊版本。</li><li>當有新版本可用時，snap 包將自動更新。</li><li>OpenStack 的 snap 包能保證與 OpenStack 的上游約束保持一致。打包的人不需要再為 OpenStack 依賴鏈維護單獨的包。這真是太爽了!</li></ul><h3 id="openstack-snap-包介紹" tabindex="-1">OpenStack snap 包介紹 <a class="header-anchor" href="#openstack-snap-包介紹" aria-label="Permalink to “OpenStack snap 包介紹”">​</a></h3><p>現在，下面這些項目已經有了相應的 snap 包：</p><ul><li><code>Keystone</code> —— 這個 snap 包為 OpenStack 提供了身份鑑證服務。</li><li><code>Glance</code> —— 這個 snap 包為 OpenStack 提供了鏡像服務。</li><li><code>Neutron</code> —— 這個 snap 包專門提供了 neutron-server 過程，作為 OpenStack 部署過程的一個 snap 包。</li><li><code>Nova</code> —— 這個 snap 包提供 OpenStack 部署過程中的 Nova 控制器組件。</li><li><code>Nova-hypervisor</code> —— 這個 snap 包提供 OpenStack 部署過程中的 hypervisor 組件，並且配置使用通過 deb 包安裝的 Libvirt/KVM + Open vSwitch 組合。這個 snap 包同時也包含 nava-lxd，這允許我們使用 nova-lxd 而不用 KVM。</li></ul>',9)),s("p",null,[n[5]||(n[5]=a("這些 snpa 包已經能讓我們部署一個簡單可工作的 OpenStack 雲。你可以在 ",-1)),e(p,{href:"https://github.com/openstack?utf8=%E2%9C%93&q=snap-&type=&language="},{default:t(()=>[...n[4]||(n[4]=[a("github",-1)])]),_:1}),n[6]||(n[6]=a(" 上找到所有這些 OpenStack snap 包的源碼。有關 OpenStack snap 包更多的細節，請參考上游存儲庫中各自的 README。在那裏，你可以找到更多有關管理 snap 包的信息，比如覆蓋默認配置、重啓服務、設置別名等等。",-1))]),n[33]||(n[33]=s("h3",{id:"想要創建自己的-openstack-snap-包嗎",tabindex:"-1"},[a("想要創建自己的 OpenStack snap 包嗎? "),s("a",{class:"header-anchor",href:"#想要創建自己的-openstack-snap-包嗎","aria-label":"Permalink to “想要創建自己的 OpenStack snap 包嗎?”"},"​")],-1)),s("p",null,[n[8]||(n[8]=a("查看 ",-1)),e(p,{href:"https://github.com/openstack-snaps/snap-cookiecutter/blob/master/README.rst"},{default:t(()=>[...n[7]||(n[7]=[a("snap cookie 工具",-1)])]),_:1}),n[9]||(n[9]=a("。我很快就會寫一篇博文，告訴你如何使用 snap cookie 工具。它非常簡單，並且能幫助你在任何時候創建一個新的 OpenStack snap 包。",-1))]),n[34]||(n[34]=l(`<h3 id="測試-openstack-snap-包" tabindex="-1">測試 OpenStack snap 包 <a class="header-anchor" href="#測試-openstack-snap-包" aria-label="Permalink to “測試 OpenStack snap 包”">​</a></h3><p>我們已經用簡單的腳本初步測試了 OpenStack snap 包。這個腳本會在單個節點上安裝 sanp 包，還會在安裝後提供額外的配置服務。來嘗試下吧：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone https://github.com/openstack-snaps/snap-test</span></span>
<span class="line"><span>cd snap-test</span></span>
<span class="line"><span>./snap-deploy</span></span></code></pre></div><p>這樣，我們就已經在 Ubuntu Xenial（16.04） 上做了所有的測試。要注意的是，這將在你的系統上安裝和配置相當多的軟件，因此你最好在可自由使用的機器上運行它。</p><h3 id="追蹤-openstack" tabindex="-1">追蹤 OpenStack <a class="header-anchor" href="#追蹤-openstack" aria-label="Permalink to “追蹤 OpenStack”">​</a></h3><p>現在，你可以從 snap 商店的邊緣通道來安裝 snap 包，比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install --edge keystone</span></span></code></pre></div><p>OpenStack 團隊正在努力使 CI/CD 配置到位，以便讓 snap 包的發佈能夠交叉追蹤 OpenStack 的發佈（比如一個追蹤 Ocata，另一個追蹤 Pike 等）。每個<ruby>軌道<rt>track</rt></ruby>都有 4 個不同的通道。每個軌道的邊緣通道將包含 OpenStack 項目對應分支最近的內容，測試、候選和穩定通道被保留用於已發佈的版本。這樣我們將看到如下的用法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install --channel=ocata/stable keystone</span></span>
<span class="line"><span>sudo snap install --channel=pike/edge keystone</span></span></code></pre></div><h3 id="其它" tabindex="-1">其它 <a class="header-anchor" href="#其它" aria-label="Permalink to “其它”">​</a></h3>`,10)),s("p",null,[n[11]||(n[11]=a("我們可以使用多個環境變量來簡化 snap 包的製作。",-1)),e(p,{href:"https://snapcraft.io/docs/reference/env"},{default:t(()=>[...n[10]||(n[10]=[a("這裏",-1)])]),_:1}),n[12]||(n[12]=a(" 有相關的説明。實際上，你無需深入的研究他們，但是在安裝完 snap 包後，你也許會想要了解這些位置：",-1))]),n[35]||(n[35]=l(`<h4 id="snap-snap-snap-name-current" tabindex="-1"><code>$SNAP == /snap/&lt;snap-name&gt;/current</code> <a class="header-anchor" href="#snap-snap-snap-name-current" aria-label="Permalink to “$SNAP == /snap/&lt;snap-name&gt;/current”">​</a></h4><p>這是 snap 包和它所有的文件掛載的位置。所有東西都是隻讀的。比如我當前安裝的 keystone，$SNAP 就是 <code>/snap/keystone/91</code>。幸好，你不需要知道當前版本號，因為在 <code>/snap/keystone/</code> 中有一個軟鏈接（LCTT 譯註：<code>/snap/keystone/current/</code>）指向當前正在使用版本對應的文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /snap/keystone/current/</span></span>
<span class="line"><span>bin                     etc      pysqlite2-doc        usr</span></span>
<span class="line"><span>command-manage.wrapper  include  snap                 var</span></span>
<span class="line"><span>command-nginx.wrapper   lib      snap-openstack.yaml</span></span>
<span class="line"><span>command-uwsgi.wrapper   meta     templates</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /snap/keystone/current/bin/</span></span>
<span class="line"><span>alembic                oslo-messaging-send-notification</span></span>
<span class="line"><span>convert-json           oslo-messaging-zmq-broker</span></span>
<span class="line"><span>jsonschema             oslo-messaging-zmq-proxy</span></span>
<span class="line"><span>keystone-manage        oslopolicy-checker</span></span>
<span class="line"><span>keystone-wsgi-admin    oslopolicy-list-redundant</span></span>
<span class="line"><span>keystone-wsgi-public   oslopolicy-policy-generator</span></span>
<span class="line"><span>lockutils-wrapper      oslopolicy-sample-generator</span></span>
<span class="line"><span>make_metadata.py       osprofiler</span></span>
<span class="line"><span>mako-render            parse_xsd2.py</span></span>
<span class="line"><span>mdexport.py            pbr</span></span>
<span class="line"><span>merge_metadata.py      pybabel</span></span>
<span class="line"><span>migrate                snap-openstack</span></span>
<span class="line"><span>migrate-repository     sqlformat</span></span>
<span class="line"><span>netaddr                uwsgi</span></span>
<span class="line"><span>oslo-config-generator</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /snap/keystone/current/usr/bin/</span></span>
<span class="line"><span>2to3               idle     pycompile     python2.7-config</span></span>
<span class="line"><span>2to3-2.7           pdb      pydoc         python2-config</span></span>
<span class="line"><span>cautious-launcher  pdb2.7   pydoc2.7      python-config</span></span>
<span class="line"><span>compose            pip      pygettext     pyversions</span></span>
<span class="line"><span>dh_python2         pip2     pygettext2.7  run-mailcap</span></span>
<span class="line"><span>easy_install       pip2.7   python        see</span></span>
<span class="line"><span>easy_install-2.7   print    python2       smtpd.py</span></span>
<span class="line"><span>edit               pyclean  python2.7</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /snap/keystone/current/lib/python2.7/site-packages/</span></span>
<span class="line"><span>...</span></span></code></pre></div><h4 id="snap-common-var-snap-snap-name-common" tabindex="-1"><code>$SNAP_COMMON == /var/snap/&lt;snap-name&gt;/common</code> <a class="header-anchor" href="#snap-common-var-snap-snap-name-common" aria-label="Permalink to “$SNAP_COMMON == /var/snap/&lt;snap-name&gt;/common”">​</a></h4><p>這個目錄用於存放系統數據，對於 snap 包的多個修訂版本這些數據是共用的。在這裏，你可以覆蓋默認配置文件和訪問日誌文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls /var/snap/keystone/common/</span></span>
<span class="line"><span>etc  fernet-keys  lib  lock  log  run</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo ls /var/snap/keystone/common/etc/</span></span>
<span class="line"><span>keystone  nginx  uwsgi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ls /var/snap/keystone/common/log/</span></span>
<span class="line"><span>keystone.log  nginx-access.log  nginx-error.log  uwsgi.log</span></span></code></pre></div><h3 id="嚴格限制" tabindex="-1">嚴格限制 <a class="header-anchor" href="#嚴格限制" aria-label="Permalink to “嚴格限制”">​</a></h3>`,7)),s("p",null,[n[14]||(n[14]=a("每個 snap 包都是在一個由 seccomp 和 AppArmor 策略構建的嚴格限制的環境中運行的。更多關於 snap 約束的細節可以在 ",-1)),e(p,{href:"https://snapcraft.io/docs/reference/confinement"},{default:t(()=>[...n[13]||(n[13]=[a("這裏",-1)])]),_:1}),n[15]||(n[15]=a(" 查看。",-1))]),n[36]||(n[36]=l('<h3 id="snap-包即將到來的新特性和更新" tabindex="-1">snap 包即將到來的新特性和更新 <a class="header-anchor" href="#snap-包即將到來的新特性和更新" aria-label="Permalink to “snap 包即將到來的新特性和更新”">​</a></h3><p>我正在期待 snap 包一些即將到來的新特性和更新（LCTT 譯註：此文發表於 7 月 6 日）：</p><ul><li>我們正在致力於實現 libvirt AppArmor 策略，這樣 nova-hypervisor 的 snap 包就能夠訪問 qcow2 的<ruby>支持文件<rt>backing files</rt></ruby>。 <ul><li>現在，作為一種變通方法，你可以將 virt-aa-helper 放在 complain 模式下：<code>sudo aa-complain /usr/lib/libvirt/virt-aa-helper</code>。</li></ul></li><li>我們還在為 snapd 開發額外的接口策略，以便為部署的實例啓用網絡連接。 <ul><li>現在你可以在 devmode 模式下安裝 nova-hypervisor snap 包，它會禁用安全限制：<code>snap install -devmode -edge nova-hypervisor</code>。</li></ul></li><li>自動連接 nova-hypervisor 的接口。我們正在努力實現在安裝時自動定義 nova-hypervisor 接口。 <ul><li>定義 AppArmor 和 seccomp 策略的接口可以允許 snap 包訪問系統的資源。</li><li>現在，你可以手動連接需要接口，在 nova-hypervisor snap 包的 README 中有相關的描述。</li></ul></li><li>命令自動定義別名。我們正在努力實現 snap 包在安裝時為命令自動定義別名。 <ul><li>這使得我們可以使用傳統的命令名。安裝 snap 包後，你將可以使用 <code>nova-manage db sync</code> 而無需再用 <code>nova.manage db sync</code>。</li><li>現在，你可以在安裝 snap 包後手動設置別名，比如：<code>snap alias nova.manage nova-manage</code>。如想獲取更多細節請查看 snap 包的 README 。</li></ul></li><li>守護進程自動定義別名。當前 snappy 僅支持為命令（非守護進程）定義別名。一旦針對守護進程的別名可用了，我們將設置它們在安裝的時候自動配置。 <ul><li>這使得我們可以使用額外的單元文件名。我們可以使用 <code>systemctl restart nova-compute</code> 而無需再用 <code>systemctl restart snap.nova.nova-compute</code>。</li></ul></li><li>snap 包資產跟蹤。這使得我們可以追蹤用來構建 snap 包的版本以便在將來構建時重複使用。</li></ul><p>如果你想多聊一些關於 snap 包的內容，你可以在 freenode 的 #openstack-snaps 這樣的 IRC 上找到我們。我們歡迎你的反饋和貢獻！感謝並祝你玩得開心！Corey</p><hr><p>作者簡介：</p><p>Corey Bryant 是 Ubuntu 的核心開發者和 Canonical 公司 OpenStack 工程團隊的軟件工程師，他主要專注於為 Ubuntu 提供 OpenStack 的安裝包以及為 Juju 進行 OpenStack 的魅力開發。他對開源軟件充滿熱情，喜歡與來自世界各地的人一起工作。</p><p>譯者簡介：</p><blockquote><p>snapcraft.io 的釘子户，對 Ubuntu Core、Snaps 和 Snapcraft 有着濃厚的興趣，並致力於將這些還在快速發展的新技術通過翻譯或原創的方式介紹到中文世界。有興趣的小夥伴也可以關注譯者個人的公眾號： <code>Snapcraft</code>，最近會在上面連載幾篇有關 Core snap 發佈策略、交付流程和驗證流程的文章，歡迎圍觀 :）</p></blockquote><hr>',10)),s("p",null,[n[17]||(n[17]=a("via: ",-1)),e(p,{href:"https://insights.ubuntu.com/2017/07/06/openstack-in-a-snap/"},{default:t(()=>[...n[16]||(n[16]=[a("https://insights.ubuntu.com/2017/07/06/openstack-in-a-snap/",-1)])]),_:1})]),s("p",null,[n[21]||(n[21]=a("作者：",-1)),e(p,{href:"https://insights.ubuntu.com/author/corey-bryant/"},{default:t(()=>[...n[18]||(n[18]=[a("Corey Bryant",-1)])]),_:1}),n[22]||(n[22]=a(" 譯者：",-1)),e(p,{href:"https://github.com/Snapcrafter"},{default:t(()=>[...n[19]||(n[19]=[a("Snapcrafter",-1)])]),_:1}),n[23]||(n[23]=a(" 校對：",-1)),e(p,{href:"https://github.com/wxy"},{default:t(()=>[...n[20]||(n[20]=[a("wxy",-1)])]),_:1})]),s("p",null,[n[26]||(n[26]=a("本文由 ",-1)),e(p,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...n[24]||(n[24]=[a("LCTT",-1)])]),_:1}),n[27]||(n[27]=a(" 原創編譯，",-1)),e(p,{href:"https://linux.cn/"},{default:t(()=>[...n[25]||(n[25]=[a("Linux中國",-1)])]),_:1}),n[28]||(n[28]=a(" 榮譽推出",-1))])])}const v=i(c,[["render",k]]);export{S as __pageData,v as default};
